/bin/bash -lc "python - <<'PY'
import inspect
from bioblend.galaxy import GalaxyInstance
print([m for m in dir(GalaxyInstance().histories) if 'histor' in m.lower() or 'copy' in m.lower() or 'clone' in m.lower()])
for m in ['copy_history','create_history','show_history']:
 try: print(m, inspect.signature(getattr(GalaxyInstance().histories,m)))
 except Exception as e: print(m, type(e).__name__)
PY"

